import { Fragment, forwardRef, useImperativeHandle, useLayoutEffect, useMemo, useRef, useState, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { createTikTokStyleCaptions, type Caption, type TikTokPage } from "@remotion/captions";

type SpeakerCaption = Caption & { speaker?: string };

interface CaptionBaseProps {
  captions: Caption[];
  combineTokensWithinMilliseconds?: number;
  holdMs?: number;
  fontSize?: number;
  fontWeight?: number;
  color?: string;
  className?: string;
}

const DEFAULT_HOLD_MS = 600;
const MIN_SILENCE_BREAK_MS = 300;

interface CaptionPageWindow {
  page: TikTokPage;
  index: number;
  speaker: string | undefined;
  startMs: number;
  speechEndMs: number;
  endMs: number;
  endsInSilence: boolean;
}

type CaptionTokenStatus = "upcoming" | "active" | "spoken";

interface CaptionTokenState {
  text: string;
  spaceBefore: boolean;
  fromMs: number;
  toMs: number;
  progress: number;
  status: CaptionTokenStatus;
}

interface CaptionPreviousPage {
  page: TikTokPage;
  pageIndex: number;
  tokens: CaptionTokenState[];
}

interface CaptionsState {
  page: TikTokPage;
  pageIndex: number;
  speaker: string | undefined;
  timeMs: number;
  activeIndex: number;
  tokens: CaptionTokenState[];
  sinceStartMs: number;
  untilEndMs: number;
  holdRoomMs: number;
  endsInSilence: boolean;
  previous: CaptionPreviousPage | null;
}

interface CaptionPagingOptions {
  combineTokensWithinMilliseconds: number;
  holdMs?: number;
}

const SENTENCE_END = /[.!?…]["')\]]*$/;

function markPageBreaks(captions: SpeakerCaption[]): Caption[] {
  return captions.map((caption, i) => {
    if (caption.pageBreakAfter !== undefined) return caption;
    const next = captions[i + 1];
    const speakerChanges =
      next !== undefined && next.speaker !== caption.speaker;
    return speakerChanges || SENTENCE_END.test(caption.text.trim())
      ? { ...caption, pageBreakAfter: true }
      : caption;
  });
}

function buildCaptionPages(
  captions: SpeakerCaption[],
  {
    combineTokensWithinMilliseconds,
    holdMs = DEFAULT_HOLD_MS,
  }: CaptionPagingOptions,
): CaptionPageWindow[] {
  if (captions.length === 0) return [];
  const { pages } = createTikTokStyleCaptions({
    captions: markPageBreaks(captions),
    combineTokensWithinMilliseconds,
    breakOnSilenceAfterMilliseconds: Math.max(holdMs, MIN_SILENCE_BREAK_MS),
  });
  const speakers = new Map<number, string | undefined>();
  for (const caption of captions) {
    if (!speakers.has(caption.startMs)) {
      speakers.set(caption.startMs, caption.speaker);
    }
  }
  const spoken = pages.filter((page) => page.tokens.length > 0);
  return spoken.map((page, index) => {
    const last = page.tokens[page.tokens.length - 1];
    const speechEndMs = last ? last.toMs : page.startMs;
    const heldUntil = speechEndMs + Math.max(0, holdMs);
    const next = spoken[index + 1];
    const endsInSilence = !next || next.startMs > heldUntil;
    const endMs = endsInSilence
      ? heldUntil
      : Math.max(page.startMs, next.startMs);
    return {
      page,
      index,
      speaker: speakers.get(page.tokens[0].fromMs),
      startMs: page.startMs,
      speechEndMs,
      endMs,
      endsInSilence,
    };
  });
}

function findWindowIndex(windows: CaptionPageWindow[], timeMs: number): number {
  let lo = 0;
  let hi = windows.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (windows[mid].startMs <= timeMs) {
      found = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (found === -1) return -1;
  return timeMs < windows[found].endMs ? found : -1;
}

function tokenProgress(fromMs: number, toMs: number, timeMs: number): number {
  if (timeMs < fromMs) return 0;
  if (toMs <= fromMs) return 1;
  return Math.min(1, (timeMs - fromMs) / (toMs - fromMs));
}

function getTokenStates(
  page: TikTokPage,
  timeMs: number,
): { activeIndex: number; tokens: CaptionTokenState[] } {
  let activeIndex = -1;
  page.tokens.forEach((token, i) => {
    if (token.fromMs <= timeMs) activeIndex = i;
  });
  const tokens = page.tokens.map(
    (token, i): CaptionTokenState => ({
      text: token.text.trim(),
      spaceBefore: i > 0 && /^\s/.test(token.text),
      fromMs: token.fromMs,
      toMs: token.toMs,
      progress: tokenProgress(token.fromMs, token.toMs, timeMs),
      status:
        i < activeIndex ? "spoken" : i === activeIndex ? "active" : "upcoming",
    }),
  );
  return { activeIndex, tokens };
}

function getCaptionsState(
  windows: CaptionPageWindow[],
  timeMs: number,
): CaptionsState | null {
  const found = findWindowIndex(windows, timeMs);
  if (found === -1) return null;
  const window = windows[found];
  const { activeIndex, tokens } = getTokenStates(window.page, timeMs);
  const before = found > 0 ? windows[found - 1] : null;
  const previous =
    before && !before.endsInSilence
      ? {
          page: before.page,
          pageIndex: before.index,
          tokens: getTokenStates(before.page, before.endMs).tokens,
        }
      : null;
  return {
    page: window.page,
    pageIndex: window.index,
    speaker: window.speaker,
    timeMs,
    activeIndex,
    tokens,
    sinceStartMs: timeMs - window.startMs,
    untilEndMs: window.endMs - timeMs,
    holdRoomMs: window.endMs - window.speechEndMs,
    endsInSilence: window.endsInSilence,
    previous,
  };
}

function getExitWindowMs(state: CaptionsState, exitMs: number): number {
  return Math.max(1, Math.min(exitMs, state.holdRoomMs));
}

function groupCaptionWords(
  tokens: CaptionTokenState[],
): { index: number; token: CaptionTokenState }[][] {
  const words: { index: number; token: CaptionTokenState }[][] = [];
  tokens.forEach((token, index) => {
    const current = words[words.length - 1];
    if (!current || token.spaceBefore) {
      words.push([{ index, token }]);
    } else {
      current.push({ index, token });
    }
  });
  return words;
}

function normalizeCaptionWord(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[^\p{L}\p{N}']/gu, "");
}

function createKeywordMatcher(
  keywords: readonly string[] = [],
): (text: string) => boolean {
  const set = new Set(keywords.map(normalizeCaptionWord).filter(Boolean));
  return (text) => set.has(normalizeCaptionWord(text));
}

function captionWordText(word: { token: CaptionTokenState }[]): string {
  return word.map(({ token }) => token.text).join("");
}

interface CaptionWordRect {
  left: number;
  top: number;
  width: number;
  height: number;
}

function sameRects(a: CaptionWordRect[], b: CaptionWordRect[]): boolean {
  return (
    a.length === b.length &&
    a.every(
      (r, i) =>
        r.left === b[i].left &&
        r.top === b[i].top &&
        r.width === b[i].width &&
        r.height === b[i].height,
    )
  );
}

function useCaptionWordRects(
  pageIndex: number,
  count: number,
): {
  wordRef: (index: number) => (el: HTMLElement | null) => void;
  rects: CaptionWordRect[] | null;
} {
  const elements = useRef<(HTMLElement | null)[]>([]);
  const [measured, setMeasured] = useState<{
    pageIndex: number;
    rects: CaptionWordRect[];
  } | null>(null);

  useLayoutEffect(() => {
    if (pageIndex === -1) return;
    const rects = elements.current.slice(0, count).map((el) =>
      el
        ? {
            left: el.offsetLeft,
            top: el.offsetTop,
            width: el.offsetWidth,
            height: el.offsetHeight,
          }
        : { left: 0, top: 0, width: 0, height: 0 },
    );
    setMeasured((prev) =>
      prev && prev.pageIndex === pageIndex && sameRects(prev.rects, rects)
        ? prev
        : { pageIndex, rects },
    );
  });

  return {
    wordRef: (index) => (el) => {
      elements.current[index] = el;
    },
    rects: measured && measured.pageIndex === pageIndex ? measured.rects : null,
  };
}

function useCaptions({
  captions,
  combineTokensWithinMilliseconds,
  holdMs = DEFAULT_HOLD_MS,
}: {
  captions: SpeakerCaption[];
  combineTokensWithinMilliseconds: number;
  holdMs?: number;
}): CaptionsState | null {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const windows = useMemo(
    () =>
      buildCaptionPages(captions, { combineTokensWithinMilliseconds, holdMs }),
    [captions, combineTokensWithinMilliseconds, holdMs],
  );
  return getCaptionsState(windows, (frame / fps) * 1000);
}

interface CaptionSpeakerProps extends CaptionBaseProps {
  captions: SpeakerCaption[];
  speakerColors?: Record<string, string>;
  upcomingOpacity?: number;
  shadow?: boolean;
}

const SPEAKER_PALETTE = ["#facc15", "#38bdf8", "#f472b6", "#4ade80"];

const ENTER_MS = 160;
const EXIT_MS = 220;
const RISE_EM = 0.14;
const REVEAL_MS = 100;
const LEGIBILITY_SHADOW =
  "0 2px 3px rgba(0, 0, 0, 0.5), 0 4px 16px rgba(0, 0, 0, 0.35)";

const enterEasing = Easing.bezier(0.2, 0.8, 0.2, 1);

const clamp = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function CaptionSpeakerBase({
  captions,
  combineTokensWithinMilliseconds = 1200,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 64,
  fontWeight = 800,
  color = "#ffffff",
  speakerColors,
  upcomingOpacity = 0.4,
  shadow = true,
  className,
}: CaptionSpeakerProps) {
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  const autoColors = useMemo(() => {
    const pinned = new Set(Object.values(speakerColors ?? {}));
    const free = SPEAKER_PALETTE.filter((c) => !pinned.has(c));
    const palette = free.length > 0 ? free : SPEAKER_PALETTE;
    const assigned = new Map<string, string>();
    for (const caption of captions) {
      const { speaker } = caption;
      if (
        speaker === undefined ||
        speakerColors?.[speaker] !== undefined ||
        assigned.has(speaker)
      ) {
        continue;
      }
      assigned.set(speaker, palette[assigned.size % palette.length]);
    }
    return assigned;
  }, [captions, speakerColors]);
  if (!state) return null;

  const enter = interpolate(
    state.previous ? ENTER_MS : state.sinceStartMs,
    [0, ENTER_MS],
    [0, 1],
    {
      ...clamp,
      easing: enterEasing,
    },
  );
  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        clamp,
      )
    : 1;

  const { speaker } = state;
  const speakerColor =
    speaker === undefined
      ? color
      : (speakerColors?.[speaker] ?? autoColors.get(speaker) ?? color);

  return (
    <div
      className={className}
      style={{
        fontSize,
        fontWeight,
        color: speakerColor,
        lineHeight: 1.2,
        textAlign: "center",
        opacity: Math.min(enter, exit),
        transform: `translateY(${(1 - enter) * RISE_EM}em)`,
      }}
    >
      {groupCaptionWords(state.tokens).map((word, w) => (
        <Fragment key={`${state.pageIndex}-${word[0].index}`}>
          {w > 0 && " "}
          <span
            style={{
              display: "inline-block",
              whiteSpace: "nowrap",
              textShadow: shadow ? LEGIBILITY_SHADOW : undefined,
            }}
          >
            {word.map(({ index, token }) => (
              <span
                key={index}
                style={{
                  opacity: interpolate(
                    state.timeMs - token.fromMs,
                    [0, REVEAL_MS],
                    [upcomingOpacity, 1],
                    clamp,
                  ),
                }}
              >
                {token.text}
              </span>
            ))}
          </span>
        </Fragment>
      ))}
    </div>
  );
}

