type CaptionSpeakerElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CaptionSpeakerBase>;

const CaptionSpeakerInner = forwardRef<
  HTMLDivElement,
  CaptionSpeakerElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CaptionSpeaker>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CaptionSpeakerBase
          {...(componentProps as unknown as ComponentProps<typeof CaptionSpeakerBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CaptionSpeaker = Interactive.withSchema({
  Component: CaptionSpeakerInner,
  componentName: "<CaptionSpeaker>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
